			if (!agent) {
				return {
					content: [{ type: "text" as const, text: `Agent '${params.agent}' is not available.` }],
				};
			}

			const focusInstructions = params.focus
				? `Focus specifically on: ${params.focus}\n\n`
				: "Analyze the following aspects:\n1. Bugs and logic errors\n2. Security vulnerabilities\n3. Performance issues\n4. Code clarity and maintainability\n\n";

			const fileContext = params.filePath ? `File: ${params.filePath}\n\n` : "";

			const prompt = `Code Review Request:\n${focusInstructions}${fileContext}Code:\n\`\`\`\n${params.code}\n\`\`\`\n\nProvide a structured review with severity levels (Critical/Warning/Info) for each finding.`;

